package binding

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/internal/flock"
	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/validation"
	"github.com/entireio/cli/internal/entireclient/userdirs"
)

// CurrentRecordVersion is the record schema version this binary writes.
// mutateRecord refuses to rewrite a record with a newer Version: encoding/json
// drops unknown fields on the round-trip, so an older binary would silently
// erase whatever a newer schema added (e.g. slice 2's adopt marker).
//
// Version 2 added LastScannedTranscriptCursor. Consequence: v1-only binaries
// refuse to mutate v2 records and degrade to a Debug-logged skip.
const CurrentRecordVersion = 2

// SessionRecord is the machine-level record of a session: which repos its
// activity has touched. Lives under userdirs.Config()/sessions/, outside any
// repo, because a session is not owned by a repo — repos are bound to it.
//
// ANY schema addition must bump CurrentRecordVersion: the refuse-on-newer
// check in mutateRecord is what protects new fields from being dropped by
// older binaries — there is no unknown-field preservation.
type SessionRecord struct {
	Version        int         `json:"version"`
	SessionID      string      `json:"session_id"`
	AgentType      string      `json:"agent_type,omitempty"`
	TranscriptPath string      `json:"transcript_path,omitempty"`
	LaunchRoot     string      `json:"launch_root,omitempty"` // worktree root of the session's hook cwd
	CreatedAt      time.Time   `json:"created_at"`
	UpdatedAt      time.Time   `json:"updated_at"`
	BoundRepos     []BoundRepo `json:"bound_repos,omitempty"`

	// LastScannedTranscriptCursor is the position already scanned for evidence
	// in the session's OWN transcript by the no-repo hook path, in the OWNING
	// AGENT'S extractor-native unit: lines for Claude Code JSONL, message index
	// for Gemini CLI's single-JSON format, the extractor's returned position
	// generally. The in-repo tap does not use it; its offsets come from session
	// state. It advances monotonically; a shrinking position (truncated/rotated
	// transcript) resets the scan to 0.
	LastScannedTranscriptCursor int `json:"last_scanned_transcript_cursor,omitempty"`
}

// BoundRepo records evidence that a session touched a repo. Keyed by
// CommonDir (clone identity — linked worktrees share it).
type BoundRepo struct {
	RepoIdentity

	FirstEvidenceAt time.Time `json:"first_evidence_at"`
	LastEvidenceAt  time.Time `json:"last_evidence_at"`
	EvidenceCount   int       `json:"evidence_count"`
	Enabled         bool      `json:"enabled"` // repo had .entire setup when last observed
}

// SessionMeta carries session identity fields for the record. They are filled
// on first write only; later writes never overwrite non-empty values.
type SessionMeta struct {
	AgentType      string
	TranscriptPath string
	LaunchRoot     string
}

func recordPath(sessionID string) (string, error) {
	// Session IDs are already filename-safe per validation.ValidateSessionID,
	// but the record store is a new attack surface for path traversal —
	// validate before touching the filesystem.
	if err := validation.ValidateSessionID(sessionID); err != nil {
		return "", fmt.Errorf("session record: %w", err)
	}
	return filepath.Join(userdirs.Config(), "sessions", sessionID+".json"), nil
}

// Evidence is one observation that a session touched a repo. Enabled notes
// whether the repo had .entire setup when observed.
type Evidence struct {
	Repo    RepoIdentity
	Enabled bool
}

// RecordBinding upserts evidence that sessionID touched a repo: it creates
// the record if absent, appends or updates the BoundRepo keyed by CommonDir,
// and bumps counters and timestamps.
func RecordBinding(ctx context.Context, sessionID string, meta SessionMeta, ev Evidence) error {
	return mutateRecord(ctx, sessionID, func(now time.Time, rec *SessionRecord) error {
		fillMetaIfEmpty(rec, meta)
		for i := range rec.BoundRepos {
			if rec.BoundRepos[i].CommonDir == ev.Repo.CommonDir {
				// Enabled is computed at the observed worktree root, and linked
				// worktrees of one clone can differ (.entire/settings.local.json
				// is worktree-local) — update the identity WITH the flag so the
				// stored pair always reflects the same (latest) observation.
				rec.BoundRepos[i].RepoIdentity = ev.Repo
				rec.BoundRepos[i].LastEvidenceAt = now
				rec.BoundRepos[i].EvidenceCount++
				rec.BoundRepos[i].Enabled = ev.Enabled
				return nil
			}
		}
		rec.BoundRepos = append(rec.BoundRepos, BoundRepo{
			RepoIdentity:    ev.Repo,
			FirstEvidenceAt: now,
			LastEvidenceAt:  now,
			EvidenceCount:   1,
			Enabled:         ev.Enabled,
		})
		return nil
	})
}

// AdvanceTranscriptCursor records that the no-repo evidence path has scanned
// sessionID's transcript up to cursor (in the owning agent's extractor-native
// unit — see SessionRecord.LastScannedTranscriptCursor). It creates the record
// if absent ("scanned, nothing found yet"), so repeat scans stay cheap even
// for sessions that never touch a repo. When reset is false the cursor only
// moves forward — max(current, cursor) — so a racing hook reporting an older
// position can never regress it. reset=true (caller detected a truncated or
// rotated transcript) stores cursor directly, permitting regression: without
// it a shrunk transcript leaves the cursor stuck at its high watermark and
// every later turn full-rescans and re-records.
func AdvanceTranscriptCursor(ctx context.Context, sessionID string, meta SessionMeta, cursor int, reset bool) error {
	return mutateRecord(ctx, sessionID, func(_ time.Time, rec *SessionRecord) error {
		fillMetaIfEmpty(rec, meta)
		if reset || cursor > rec.LastScannedTranscriptCursor {
			rec.LastScannedTranscriptCursor = cursor
		}
		return nil
	})
}

// fillMetaIfEmpty applies the first-write-only rule for session identity
// fields: later writes never overwrite non-empty values.
func fillMetaIfEmpty(rec *SessionRecord, meta SessionMeta) {
	if rec.AgentType == "" {
		rec.AgentType = meta.AgentType
	}
	if rec.TranscriptPath == "" {
		rec.TranscriptPath = meta.TranscriptPath
	}
	if rec.LaunchRoot == "" {
		rec.LaunchRoot = meta.LaunchRoot
	}
}

// LoadRecord reads the session record for sessionID. Returns (nil, nil) when
// no record exists; a malformed record is an error.
func LoadRecord(_ context.Context, sessionID string) (*SessionRecord, error) {
	path, err := recordPath(sessionID)
	if err != nil {
		return nil, err
	}
	return loadRecordFromFile(path)
}

func loadRecordFromFile(path string) (*SessionRecord, error) {
	data, err := os.ReadFile(path) //nolint:gosec // path is userdirs.Config()-rooted with a validated session ID
	if os.IsNotExist(err) {
		return nil, nil //nolint:nilnil // absence is a normal outcome, distinct from a malformed record
	}
	if err != nil {
		return nil, fmt.Errorf("read session record: %w", err)
	}
	var rec SessionRecord
	if err := json.Unmarshal(data, &rec); err != nil {
		return nil, fmt.Errorf("parse session record %s: %w", path, err)
	}
	return &rec, nil
}

// recordLockTimeout bounds the wait for the session-record flock. Hook
// contexts carry no deadline, and without one AcquireContext blocks in the
// kernel indefinitely — a wedged lock holder would then stall the hook,
// breaking the tap's never-block-capture promise. This layer is best-effort
// by design, so timing out and dropping the evidence is the correct
// degradation.
const recordLockTimeout = 2 * time.Second

// mutateRecord runs fn over the session record under an exclusive file lock:
// MkdirAll → flock → load-or-create → fn → atomic write. Two hook processes
// (agent + git hook) can race on the same session; the flock serializes them.
// fn receives the single clock reading that also stamps CreatedAt/UpdatedAt,
// so every timestamp written by one mutation agrees.
func mutateRecord(ctx context.Context, sessionID string, fn func(now time.Time, rec *SessionRecord) error) error {
	path, err := recordPath(sessionID)
	if err != nil {
		return err
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		return fmt.Errorf("create sessions directory: %w", err)
	}
	lockCtx, cancel := context.WithTimeout(ctx, recordLockTimeout)
	defer cancel()
	release, err := flock.AcquireContext(lockCtx, path+".lock")
	if err != nil {
		return fmt.Errorf("lock session record: %w", err)
	}
	defer release()

	rec, err := loadRecordFromFile(path)
	if err != nil {
		return err
	}
	if rec != nil && rec.Version > CurrentRecordVersion {
		return fmt.Errorf("session record %s has version %d, newer than this binary's %d: refusing to rewrite (unknown fields would be dropped)",
			path, rec.Version, CurrentRecordVersion)
	}
	now := time.Now().UTC()
	if rec == nil {
		rec = &SessionRecord{SessionID: sessionID, CreatedAt: now}
	}
	rec.Version = CurrentRecordVersion // normalize legacy/zero-version records upward
	if err := fn(now, rec); err != nil {
		return err
	}
	rec.UpdatedAt = now
	data, err := json.MarshalIndent(rec, "", "  ")
	if err != nil {
		return fmt.Errorf("marshal session record: %w", err)
	}
	if err := jsonutil.WriteFileAtomic(path, data, 0o600); err != nil {
		return fmt.Errorf("write session record: %w", err)
	}
	return nil
}

// Package binding records which repositories an agent session's activity
// touches. Slice 1 (this package's initial state) only OBSERVES: a resolver
// maps out-of-repo evidence paths to their repos and a machine-level session
// record stores the bindings. Nothing acts on the record yet; the additive
// adopt slice consumes it.
//
// Resolver results — including not-a-repo misses — are cached for the
// lifetime of the process: the resolver is designed for short-lived hook
// processes, and a long-lived consumer (e.g. entire mcp) must either accept
// stale results or call ClearResolveCache.
package binding

import (
	"context"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"sync"

	"github.com/entireio/cli/cmd/entire/cli/execx"
)

// RepoIdentity names a repo by its worktree root and (absolute) git common
// dir. The common dir is the clone-wide key: linked worktrees share it.
type RepoIdentity struct {
	WorktreeRoot string `json:"worktree_root"`
	CommonDir    string `json:"common_dir"`
}

// maxAncestorWalk bounds the walk toward an existing ancestor so garbage
// paths (agent hallucinations, hosts with unbounded virtual trees) cannot
// spin the resolver. 10 levels is generous: evidence paths deleted more than
// ten directories deep are vanishingly rare, and exceeding the bound only
// costs a piece of binding evidence — capture itself is never affected.
const maxAncestorWalk = 10

var (
	resolveMu    sync.RWMutex
	resolveCache = map[string]resolveResult{}
)

type resolveResult struct {
	id RepoIdentity
	ok bool
}

// ResolveRepoForPath maps an absolute file path to the repo containing it.
// The file need not exist (deleted files are evidence too): resolution walks
// up to the nearest existing ancestor directory, bounded, and runs one
// `git -C <dir> rev-parse --show-toplevel --git-common-dir`. Results —
// including "not a repo" — are cached per directory, because one turn can
// carry many paths from the same foreign tree. Relative input returns miss:
// absolutizing against an ambient cwd here would attribute evidence to the
// wrong repo; that responsibility stays with the caller, which knows the
// agent's cwd.
func ResolveRepoForPath(ctx context.Context, absPath string) (RepoIdentity, bool) {
	if !filepath.IsAbs(absPath) {
		return RepoIdentity{}, false
	}
	dir := nearestExistingAncestor(filepath.Dir(absPath))
	if dir == "" {
		return RepoIdentity{}, false
	}

	resolveMu.RLock()
	cached, hit := resolveCache[dir]
	resolveMu.RUnlock()
	if hit {
		return cached.id, cached.ok
	}

	id, ok := resolveViaGit(ctx, dir)
	resolveMu.Lock()
	resolveCache[dir] = resolveResult{id: id, ok: ok}
	resolveMu.Unlock()
	return id, ok
}

func nearestExistingAncestor(dir string) string {
	for range maxAncestorWalk {
		if info, err := os.Stat(dir); err == nil && info.IsDir() {
			return dir
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return ""
		}
		dir = parent
	}
	return ""
}

func resolveViaGit(ctx context.Context, dir string) (RepoIdentity, bool) {
	// --path-format=absolute (git ≥2.31) emits both outputs absolute AND
	// symlink-canonical, so the same clone reached via a symlink and via its
	// real path yields one CommonDir — RepoIdentity's clone-wide-key
	// invariant. No minimum git version is documented for the CLI, so support
	// is probed once per process (a rev-parse failure cannot distinguish
	// flag-unsupported from not-a-repo, and retrying flagless on every miss
	// would double the forks) and older gits take the flagless path.
	return runRevParse(ctx, dir, supportsPathFormat(ctx))
}

var (
	pathFormatMu        sync.Mutex
	pathFormatSupported *bool // nil = not yet probed
)

// supportsPathFormat reports whether the installed git understands
// --path-format (added in 2.31, released 2021). Probed via one `git version`
// fork per process; an unparseable or failing probe conservatively selects
// the flagless fallback, which is correct on every git.
func supportsPathFormat(ctx context.Context) bool {
	pathFormatMu.Lock()
	defer pathFormatMu.Unlock()
	if pathFormatSupported == nil {
		v := probePathFormatSupport(ctx)
		pathFormatSupported = &v
	}
	return *pathFormatSupported
}

func probePathFormatSupport(ctx context.Context) bool {
	out, err := execx.NonInteractive(ctx, "git", "version").Output()
	if err != nil {
		return false
	}
	// "git version 2.50.1 (Apple Git-155)" / "git version 2.31.0.windows.1"
	fields := strings.Fields(string(out))
	if len(fields) < 3 {
		return false
	}
	parts := strings.SplitN(fields[2], ".", 3)
	if len(parts) < 2 {
		return false
	}
	major, majErr := strconv.Atoi(parts[0])
	minor, minErr := strconv.Atoi(parts[1])
	if majErr != nil || minErr != nil {
		return false
	}
	return major > 2 || (major == 2 && minor >= 31)
}

func runRevParse(ctx context.Context, dir string, absoluteFlag bool) (RepoIdentity, bool) {
	args := []string{"-C", dir, "rev-parse"}
	if absoluteFlag {
		args = append(args, "--path-format=absolute")
	}
	args = append(args, "--show-toplevel", "--git-common-dir")
	out, err := execx.NonInteractive(ctx, "git", args...).Output()
	if err != nil {
		return RepoIdentity{}, false // not a repo, git missing, flag unsupported, etc. — a normal miss
	}
	lines := strings.Split(strings.TrimSpace(string(out)), "\n")
	if len(lines) != 2 {
		return RepoIdentity{}, false
	}
	root := strings.TrimSpace(lines[0])
	commonDir := strings.TrimSpace(lines[1])
	if !absoluteFlag {
		// Pre-2.31 fallback: rev-parse emits ../.git style relative output
		// depending on depth — resolve against the queried dir, never the
		// process cwd — and canonicalize via EvalSymlinks, because the joined
		// path preserves symlink components --path-format=absolute would have
		// resolved, which would split one clone into two CommonDir keys.
		if !filepath.IsAbs(commonDir) {
			commonDir = filepath.Join(dir, commonDir)
		}
		root = canonicalize(root)
		commonDir = canonicalize(commonDir)
	}
	commonDir = filepath.Clean(commonDir)
	if root == "" || commonDir == "" {
		return RepoIdentity{}, false
	}
	return RepoIdentity{WorktreeRoot: root, CommonDir: commonDir}, true
}

// canonicalize resolves symlinks best-effort: on error (e.g. a component
// disappeared mid-resolution) the cleaned input is still a usable identity.
func canonicalize(path string) string {
	resolved, err := filepath.EvalSymlinks(path)
	if err != nil {
		return filepath.Clean(path)
	}
	return resolved
}

// ClearResolveCache resets the resolver cache and the cached
// --path-format support probe. Test-only.
func ClearResolveCache() {
	resolveMu.Lock()
	resolveCache = map[string]resolveResult{}
	resolveMu.Unlock()
	pathFormatMu.Lock()
	pathFormatSupported = nil
	pathFormatMu.Unlock()
}

// ResolveCacheSizeForTesting reports the number of cached directory
// resolutions. Test-only.
func ResolveCacheSizeForTesting() int {
	resolveMu.RLock()
	defer resolveMu.RUnlock()
	return len(resolveCache)
}

// binding_norepo.go is the evidence-only hook path for a cwd outside any git
// repo. Launching an agent from a parent directory above sibling repos
// (~/dev/acme — #1098's loudest scenario) fires every hook with a non-repo
// cwd, where checkpoint capture is impossible; the session's evidence can
// still name the repos it touched. This path parses the event, extracts file
// paths, and records foreign repos in the machine-level session record —
// nothing else: no session state, no checkpoints, no logging.Init, no repo
// writes.
package cli

import (
	"bytes"
	"context"
	"io"
	"log/slog"
	"os"
	"path/filepath"
	"runtime/debug"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/binding"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

// recordNoRepoEvidence is the no-repo counterpart of the in-repo binding tap:
// best-effort, evidence-only, and crash-proof — once user-level hooks exist,
// it runs on EVERY hook in EVERY non-repo cwd, so it must be cheap and can
// never block the agent. For non-evidence verbs the added cost over the old
// silent bail is one registry map lookup plus one stdin parse (~270ns + 2
// allocs measured): the verb→event-type mapping is derivable from hookName,
// but no agent exposes it pre-parse, and the saving would be negligible since
// the high-frequency verbs are evidence-bearing and must parse anyway.
//
// logging.Init never ran here (initHookLogging no-ops outside a repo), so only
// logging.Debug may be used: pre-Init it is a silent no-op, while
// Info/Warn/Error would leak raw slog text onto the agent's stderr.
func recordNoRepoEvidence(ctx context.Context, agentName types.AgentName, hookName string, stdin io.Reader) {
	logCtx := logging.WithComponent(ctx, "binding")
	defer func() {
		if r := recover(); r != nil {
			logging.Debug(logCtx, "no-repo evidence path panicked; evidence dropped, agent unaffected",
				slog.Any("panic", r),
				slog.String("stack", string(debug.Stack())))
		}
	}()

	ag, err := agent.Get(agentName)
	if err != nil {
		return
	}
	// Deliberately no shouldSkipForwardedHook here: it needs a repo root. A
	// forwarded hook (e.g. a Cursor-forwarded claude event) records evidence
	// under the parsing agent's type — harmless for evidence, and the record's
	// meta is first-write-only.
	handler, ok := agent.AsHookSupport(ag)
	if !ok {
		return
	}
	event, parseErr := handler.ParseHookEvent(ctx, hookName, stdin)
	if parseErr != nil || event == nil {
		return
	}
	// Require a real session ID: an empty ID has nothing to key the record on,
	// and the tap's unknownSessionID guard only covers its own entry point —
	// the cursor write below bypasses it.
	if event.SessionID == "" || event.SessionID == unknownSessionID {
		return
	}

	meta := binding.SessionMeta{
		AgentType:      string(ag.Type()),
		TranscriptPath: event.SessionRef,
		LaunchRoot:     "", // no repo at the hook cwd
	}

	// Non-evidence events are listed explicitly (not folded into the default)
	// so the exhaustive linter forces a review when a new EventType is added —
	// a new evidence-bearing type must be routed here deliberately.
	switch event.Type {
	case agent.ToolUse:
		// currentWorktreeRoot="" — there is no current repo, so every resolved
		// repo is foreign and the same-worktree skip can never match.
		recordForeignEvidence(ctx, event.SessionID, meta, "", absoluteToolUsePaths(event))
	case agent.TurnEnd:
		if event.SessionRef == "" {
			return
		}
		recordForeignEvidence(ctx, event.SessionID, meta, "", scanTranscriptForeign(logCtx, ag, event, meta))
	case agent.SessionStart, agent.TurnStart, agent.Compaction, agent.SessionEnd,
		agent.SubagentStart, agent.SubagentEnd, agent.ModelUpdate:
		// No path evidence; the session-start notice UX is a separate slice.
	default:
	}
}

// absoluteToolUsePaths flattens a ToolUse event's path payloads to absolute
// paths. Relative paths join onto the event's CWD — the tool's OWN working
// directory, which the payload carries precisely so relative paths can be
// resolved — and are skipped when it is empty (no join base means any guess
// could bind the wrong repo).
func absoluteToolUsePaths(event *agent.Event) []string {
	groups := [][]string{event.ModifiedFiles, event.NewFiles, event.DeletedFiles}
	var out []string
	for _, group := range groups {
		for _, p := range group {
			switch {
			case p == "":
			case filepath.IsAbs(p):
				out = append(out, p)
			case event.CWD != "":
				out = append(out, filepath.Join(event.CWD, p))
			}
		}
	}
	return out
}

// scanTranscriptForeign extracts modified-file evidence from the turn's new
// transcript span and returns only ABSOLUTE paths: transcript-level extraction
// has no safe join base — the hook's cwd is the launch dir, but tool calls in
// the transcript may have run after the agent cd'd elsewhere (unlike
// per-ToolUse payloads, whose CWD is the tool's own) — so dropping relative
// paths is the only non-guessing option.
//
// The scan cursor lives in the machine session record and is EXTRACTOR-NATIVE:
// lines for Claude Code's JSONL, a message index for Gemini CLI's single-JSON
// transcript (its extractor interprets startOffset as a message index and
// returns a message count). Cursor advancement means each transcript unit is
// scanned at most once across the session, so the tap's per-turn bounds
// compose with a per-unit-once guarantee. The cursor is ALWAYS advanced, even
// when no paths were found, to keep repeat scans cheap for chatty no-repo
// sessions — consequence: every no-repo session with a turn-end creates a
// cursor-only record on its first Stop, even if it never touches a repo
// (retention for these is part of slice 2's parked retention story).
func scanTranscriptForeign(logCtx context.Context, ag agent.Agent, event *agent.Event, meta binding.SessionMeta) []string {
	cursor := 0
	rec, err := binding.LoadRecord(logCtx, event.SessionID)
	switch {
	case err != nil:
		// Degrade to a full scan.
		logging.Debug(logCtx, "no-repo evidence: session record unreadable, rescanning from 0",
			slog.String("session_id", event.SessionID),
			slog.String("error", err.Error()))
	case rec != nil:
		cursor = rec.LastScannedTranscriptCursor
	}

	var files []string
	var nextCursor int
	truncated := false
	if subagentExtractor, ok := agent.AsSubagentAwareExtractor(ag); ok {
		// Claude-shaped JSONL: read once, count complete lines ourselves.
		data, readErr := os.ReadFile(event.SessionRef)
		if readErr != nil {
			return nil
		}
		// No +1 for a trailing partial line — transcript.SliceFromLine skips
		// exactly N complete lines, so an uncounted partial line is included
		// in this scan and re-scanned once completed: never skipped, at most
		// one line re-extracted.
		nextCursor = bytes.Count(data, []byte("\n"))
		if nextCursor < cursor {
			cursor = 0
			truncated = true
		}
		var exErr error
		files, exErr = subagentExtractor.ExtractAllModifiedFiles(data, cursor,
			paths.SubagentsDir(filepath.Dir(event.SessionRef), event.SessionID))
		if exErr != nil {
			// Don't advance past unextracted content — retry next turn.
			logging.Debug(logCtx, "no-repo evidence: transcript extraction failed",
				slog.String("session_id", event.SessionID),
				slog.String("error", exErr.Error()))
			return nil
		}
	} else if analyzer, ok := agent.AsTranscriptAnalyzer(ag); ok {
		// The extractor reads the file itself and its RETURNED position is the
		// next cursor, in whatever unit the agent uses.
		var exErr error
		files, nextCursor, exErr = analyzer.ExtractModifiedFilesFromOffset(event.SessionRef, cursor)
		if exErr == nil && nextCursor < cursor {
			// Truncated/rotated in the extractor's own coordinates: one
			// immediate rescan from 0.
			truncated = true
			files, nextCursor, exErr = analyzer.ExtractModifiedFilesFromOffset(event.SessionRef, 0)
		}
		if exErr != nil {
			logging.Debug(logCtx, "no-repo evidence: transcript extraction failed",
				slog.String("session_id", event.SessionID),
				slog.String("error", exErr.Error()))
			return nil
		}
	} else {
		return nil
	}

	if err := binding.AdvanceTranscriptCursor(logCtx, event.SessionID, meta, nextCursor, truncated); err != nil {
		logging.Debug(logCtx, "no-repo evidence: failed to advance transcript cursor",
			slog.String("session_id", event.SessionID),
			slog.String("error", err.Error()))
	}

	absolute := make([]string, 0, len(files))
	for _, f := range files {
		if filepath.IsAbs(f) {
			absolute = append(absolute, f)
		}
	}
	return absolute
}

