22	// this bound a turn full of non-repo paths forks unboundedly, while repeat
23	// dirs are free resolver-cache hits, so distinct dirs tracks forks
24	// precisely), and maxForeignReposPerTurn caps how many distinct foreign
25	// repos are recorded. The loop stops when either trips.
26	const (
27		maxForeignReposPerTurn       = 8
28		maxForeignResolutionsPerTurn = 16
29	)
