37	//     clamp discarded.
38	//   - keptRelGroups: currentWorktreeRoot-relative KEPT paths. Kept paths can
39	//     still be cross-repo evidence when they land inside a repo NESTED under
40	//     the session repo's root (e.g. $HOME is a dotfiles repo and the session
41	//     runs there: every other repo on the machine is path-wise inside it, so
42	//     nothing ever becomes foreign). Detection is a stat-only ancestor walk
43	//     (nestedRepoEvidencePaths) — the no-nested-repos common case costs zero
44	//     git forks — and registered submodules are excluded as part of the
45	//     parent project. The kept slices are only READ here: the lists feeding
46	//     checkpoint capture stay byte-identical (slice 1's reviewed invariant).
47	//
48	// Best-effort throughout: every failure logs Debug and moves on, and a panic
49	// is swallowed the same way — capture is never blocked. The empty-input early
50	// return keeps the hot path (every single-repo turn with no evidence
51	// candidates) nearly free; turns with kept paths additionally pay the stat
52	// walk, never a fork.
53	func recordForeignEvidence(ctx context.Context, sessionID string, meta binding.SessionMeta, currentWorktreeRoot string, foreignPaths []string, keptRelGroups ...[]string) {
54		logCtx := logging.WithComponent(ctx, "binding")
55		defer func() {
56			if r := recover(); r != nil {
57				logging.Debug(logCtx, "binding tap panicked; evidence dropped, capture unaffected",
58					slog.Any("panic", r),
59					slog.String("stack", string(debug.Stack())))
60			}
61		}()
62		if len(foreignPaths) == 0 && !anyPaths(keptRelGroups) {
63			return
64		}
65		// unknownSessionID passes ValidateSessionID and would create a
66		// sessions/unknown.json aggregating unrelated sessions.
67		if sessionID == "" || sessionID == unknownSessionID {
68			return
69		}
70		_, span := perf.Start(ctx, "binding_tap")
71		defer span.End()
72	
73		// Nested-repo detection shares the resolution/repo budget below: detected
74		// paths simply join the same loop, so a pathological turn cannot fork more
75		// than maxForeignResolutionsPerTurn git processes in total.
76		if nested := nestedRepoEvidencePaths(currentWorktreeRoot, keptRelGroups); len(nested) > 0 {
77			foreignPaths = append(append(make([]string, 0, len(foreignPaths)+len(nested)), foreignPaths...), nested...)
78		}
79		if len(foreignPaths) == 0 {
80			return
81		}
82	
83		// The resolver returns symlink-canonical roots; canonicalize ours the
84		// same way (best-effort) so a symlink-aliased cwd cannot defeat the
85		// own-worktree skip below.
86		if canonical, err := filepath.EvalSymlinks(currentWorktreeRoot); err == nil {
87			currentWorktreeRoot = canonical
88		}
89	
90		found := make(map[string]binding.RepoIdentity)
91		order := make([]string, 0, len(foreignPaths))
92		// Budget by filepath.Dir(path): the resolver's real cache key is the
93		// nearest EXISTING ancestor, but at this layer filepath.Dir is the right
94		// cheap proxy — a path whose dir was already probed is a guaranteed cache
95		// hit, so many paths in one foreign dir spend the budget exactly once and
96		// cannot starve later repos.
97		seenDirs := make(map[string]struct{})
98		for _, p := range foreignPaths {
99			if len(found) >= maxForeignReposPerTurn {
100				logging.Debug(logCtx, "binding tap repo cap reached, skipping remaining evidence paths",
101					slog.String("session_id", sessionID),
102					slog.Int("found", len(found)))
103				break
104			}
105			dir := filepath.Dir(p)
106			if _, probed := seenDirs[dir]; !probed {
107				if len(seenDirs) >= maxForeignResolutionsPerTurn {
108					// A path in an already-probed dir can only re-yield a repo we
109					// have, so nothing recordable remains once new dirs are out
110					// of budget.
111					logging.Debug(logCtx, "binding tap resolution budget exhausted, skipping remaining evidence paths",
112						slog.String("session_id", sessionID),
113						slog.Int("distinct_dirs", len(seenDirs)),
114						slog.Int("found", len(found)))
