116				}
117				seenDirs[dir] = struct{}{}
118			}
119			id, ok := binding.ResolveRepoForPath(ctx, p)
120			if !ok {
121				continue
122			}
123			// Same worktree = not foreign. Worktree root alone identifies it: two
124			// clones cannot share a worktree root, and a different worktree of
125			// the same clone has a different root — that one IS recorded (slice 2
126			// decides what it means).
127			if id.WorktreeRoot == currentWorktreeRoot {
128				continue
129			}
130			if _, seen := found[id.CommonDir]; !seen {
131				found[id.CommonDir] = id
132				order = append(order, id.CommonDir)
133			}
134		}
135	
136		for _, commonDir := range order {
137			id := found[commonDir]
138			enabled := settings.IsSetUpAtRoot(id.WorktreeRoot)
139			if err := binding.RecordBinding(ctx, sessionID, meta, binding.Evidence{Repo: id, Enabled: enabled}); err != nil {
140				logging.Debug(logCtx, "failed to record session binding",
141					slog.String("session_id", sessionID),
142					slog.String("repo", id.WorktreeRoot),
143					slog.String("error", err.Error()))
144				continue
145			}
146			logging.Debug(logCtx, "recorded foreign repo evidence",
147				slog.String("session_id", sessionID),
148				slog.String("repo", id.WorktreeRoot),
149				slog.Bool("enabled", enabled))
150		}
151	}
