185			return nil
186		}
187		prefix := repoRoot + string(filepath.Separator)
188		// nestedRootByDir memoizes the ancestor walk per visited directory
189		// ("" = no intermediate .git), so one turn's stats are bounded by the
190		// number of distinct directories in the kept tree, not by path count.
191		nestedRootByDir := map[string]string{}
192		var submodulePaths map[string]struct{}
193		submodulesLoaded := false
194		seenDirs := map[string]struct{}{}
195		seenRoots := map[string]struct{}{}
196		var out []string
197		for _, group := range keptRelGroups {
198			for _, rel := range group {
199				if rel == "" {
200					continue
201				}
202				abs := filepath.Join(repoRoot, filepath.FromSlash(rel))
203				if !strings.HasPrefix(abs, prefix) {
204					continue
205				}
206				dir := filepath.Dir(abs)
207				if _, done := seenDirs[dir]; done {
208					continue
209				}
210				seenDirs[dir] = struct{}{}
211				nestedRoot := nestedRepoRootFor(dir, repoRoot, nestedRootByDir)
212				if nestedRoot == "" {
213					continue
214				}
215				if _, done := seenRoots[nestedRoot]; done {
216					continue
217				}
218				seenRoots[nestedRoot] = struct{}{}
219				if !submodulesLoaded {
220					submodulePaths = registeredSubmodulePaths(repoRoot)
221					submodulesLoaded = true
222				}
223				relRoot, err := filepath.Rel(repoRoot, nestedRoot)
224				if err != nil {
225					continue
226				}
227				if isRegisteredSubmodulePath(filepath.ToSlash(relRoot), submodulePaths) {
228					continue
229				}
230				out = append(out, abs)
231			}
232		}
233		return out
234	}
