236	// isRegisteredSubmodulePath reports whether relRoot (slash-normalized,
237	// repo-relative) is a registered submodule path or lies UNDER one: a repo
238	// nested inside a registered submodule (typically the submodule's own
239	// submodule) is transitively part of the parent project, so binding to it
240	// would be the same noise as binding to the submodule itself. Containment
241	// requires a "/" boundary — "vendor/subextra" does not match "vendor/sub".
242	func isRegisteredSubmodulePath(relRoot string, registered map[string]struct{}) bool {
243		if _, ok := registered[relRoot]; ok {
244			return true
245		}
246		for reg := range registered {
247			if strings.HasPrefix(relRoot, reg+"/") {
248				return true
249			}
250		}
251		return false
252	}
