254	// nestedRepoRootFor walks from dir up to (exclusive) repoRoot and returns the
255	// first (innermost) ancestor holding a .git entry, or "" when there is none.
256	// Nonexistent components (deleted files are evidence too) simply fail their
257	// Lstat and the walk continues upward. memo carries results across paths in
258	// one turn; every visited level shares the walk's outcome.
259	func nestedRepoRootFor(dir, repoRoot string, memo map[string]string) string {
260		prefix := repoRoot + string(filepath.Separator)
261		var visited []string
262		nestedRoot := ""
263		for d := dir; d != repoRoot && strings.HasPrefix(d, prefix); d = filepath.Dir(d) {
264			if cached, ok := memo[d]; ok {
