266				break
267			}
268			visited = append(visited, d)
269			if _, err := os.Lstat(filepath.Join(d, ".git")); err == nil {
270				nestedRoot = d
271				break
272			}
273		}
274		for _, d := range visited {
275			memo[d] = nestedRoot
276		}
277		return nestedRoot
278	}
